import{_ as t,o as s,c as l,a3 as a}from"./chunks/framework.bGC-1KKp.js";const g=JSON.parse(`{"title":"Lab 03 — Le plan d'essai","description":"","frontmatter":{"title":"Lab 03 — Le plan d'essai","aside":false},"headers":[],"relativePath":"labs/lab03-plan-essai.md","filePath":"labs/lab03-plan-essai.md"}`),i={name:"labs/lab03-plan-essai.md"};function n(r,e,o,u,d,c){return s(),l("div",null,[...e[0]||(e[0]=[a('<h1 id="lab-03-—-le-plan-d-essai" tabindex="-1">Lab 03 — Le plan d&#39;essai <a class="header-anchor" href="#lab-03-—-le-plan-d-essai" aria-label="Permalink to &quot;Lab 03 — Le plan d&#39;essai&quot;">​</a></h1><div class="bg-blue-50 border border-blue-200 text-blue-900 rounded-lg p-4 mb-5"><strong>Objectifs du laboratoire</strong><br><ul class="list-disc pl-5"><li>Trouver les outils qui pourraient répondre à une question technique du mandat, à partir de sources dont on a jugé la fiabilité.</li><li>Lire la grille de prix de chaque outil et estimer ce qu&#39;il coûterait au client pendant un an.</li><li>Préparer une liste d&#39;essais rigoureux, les mêmes pour chaque outil, tirée des besoins réels du mandat.</li></ul></div><div class="bg-yellow-50 border border-yellow-200 text-yellow-900 rounded-lg p-4 mb-5"><strong>Modalités</strong><br><ul class="list-disc pl-5"><li>Avec <strong>votre équipe de la session</strong>.</li><li>Durée : environ 50 minutes en classe. Ce qui n&#39;est pas terminé se complète avant la séance 4.</li><li>Remise : la fiche remplie, déposée dans l&#39;<strong>équipe Teams du cours</strong>. Travail <strong>formatif</strong>. À la séance 4, vous ferez les essais prévus ici : un plan incomplet, c&#39;est une séance 4 perdue.</li></ul></div><hr><h2 id="contexte" tabindex="-1">Contexte <a class="header-anchor" href="#contexte" aria-label="Permalink to &quot;Contexte&quot;">​</a></h2><p>Mélanie vous a demandé « est-ce que c&#39;est faisable ? ». Pour répondre, il faut savoir <strong>quelles technologies existent</strong> et <strong>ce qu&#39;elles valent vraiment</strong>. Ce soir, votre équipe devient spécialiste d&#39;<strong>une</strong> question. À la séance 4, vous passerez de la lecture à l&#39;essai.</p><blockquote><p><strong>Règle d&#39;or, encore :</strong> on ne choisit pas d&#39;outil. On en trouve deux ou trois <strong>qui pourraient convenir</strong>, et on prépare le moyen de les comparer équitablement. Le choix viendra à l&#39;évaluation 2.</p></blockquote><hr><h2 id="preparation" tabindex="-1">Préparation (5 min) <a class="header-anchor" href="#preparation" aria-label="Permalink to &quot;Préparation (5 min) {#preparation}&quot;">​</a></h2><ul class="checklist"><li><label><input type="checkbox"><span class="check-text">Noter la question reçue au tirage (Q1 à Q5) — voir le tableau ci-dessous</span></label></li><li><label><input type="checkbox"><span class="check-text"><a href="./../fiches/lab03-fiche-plan-essai.docx" download>Télécharger la fiche du plan d&#39;essai (Word)</a> et la placer dans le dossier partagé de l&#39;équipe</span></label></li><li><label><input type="checkbox"><span class="check-text">Ouvrir votre fiche du Lab 02 : les contraintes et les exigences liées à votre question vont servir</span></label></li><li><label><input type="checkbox"><span class="check-text">Ouvrir le <a href="./../mandat/" target="_blank">mandat</a> dans un onglet</span></label></li></ul><h3 id="les-cinq-questions" tabindex="-1">Les cinq questions <a class="header-anchor" href="#les-cinq-questions" aria-label="Permalink to &quot;Les cinq questions&quot;">​</a></h3><table tabindex="0"><thead><tr><th style="text-align:center;">#</th><th style="text-align:left;">La question</th><th style="text-align:left;">Pour vous lancer (mots-clés de recherche)</th></tr></thead><tbody><tr><td style="text-align:center;"><strong>Q1</strong></td><td style="text-align:left;">Comment réserver et payer en ligne ?</td><td style="text-align:left;"><em>logiciel de réservation activités</em>, <em>tour operator booking software</em>, <em>channel manager Viator</em></td></tr><tr><td style="text-align:center;"><strong>Q2</strong></td><td style="text-align:left;">Comment faire signer la décharge avant l&#39;arrivée ?</td><td style="text-align:left;"><em>décharge électronique</em>, <em>digital waiver software</em>, <em>waiver offline kiosk</em></td></tr><tr><td style="text-align:center;"><strong>Q3</strong></td><td style="text-align:left;">Sur quelle plateforme construire le site ?</td><td style="text-align:left;"><em>constructeur de site</em>, <em>CMS pour PME</em>, <em>transfert de site Wix</em></td></tr><tr><td style="text-align:center;"><strong>Q4</strong></td><td style="text-align:left;">Comment montrer les vidéos sans ralentir le site ?</td><td style="text-align:left;"><em>hébergement vidéo</em>, <em>background video performance</em>, <em>video streaming service pricing</em></td></tr><tr><td style="text-align:center;"><strong>Q5</strong></td><td style="text-align:left;">Comment offrir le site en français et en anglais ?</td><td style="text-align:left;"><em>site multilingue</em>, <em>website translation plugin</em>, <em>traduction automatique site Web</em></td></tr></tbody></table><hr><h2 id="partie-1" tabindex="-1">Partie 1 — Comprendre la question (5 min) <a class="header-anchor" href="#partie-1" aria-label="Permalink to &quot;Partie 1 — Comprendre la question (5 min) {#partie-1}&quot;">​</a></h2><p>Avant de chercher un seul outil, écrivez dans la fiche <strong>ce que l&#39;outil devra absolument faire</strong> pour Aventure Saint-Maurice. Reprenez les exigences et les contraintes du Lab 02 qui touchent votre question.</p><table tabindex="0"><thead><tr><th style="text-align:left;">Colonne</th><th style="text-align:left;">Ce qu&#39;on y écrit</th></tr></thead><tbody><tr><td style="text-align:left;"><strong>Besoin</strong></td><td style="text-align:left;">Ce que l&#39;outil doit permettre, dans vos mots</td></tr><tr><td style="text-align:left;"><strong>Source dans le mandat</strong></td><td style="text-align:left;">Le document et un court extrait</td></tr><tr><td style="text-align:left;"><strong>Essentiel ou souhaitable ?</strong></td><td style="text-align:left;"><strong>E</strong> si le projet échoue sans ça, <strong>S</strong> sinon</td></tr></tbody></table><p>Visez <strong>6 à 8 besoins</strong>, dont au moins <strong>deux non fonctionnels</strong> (vitesse, sécurité, accessibilité, Loi 25, appareils).</p><hr><h2 id="partie-2" tabindex="-1">Partie 2 — Trouver les outils (15 min) <a class="header-anchor" href="#partie-2" aria-label="Permalink to &quot;Partie 2 — Trouver les outils (15 min) {#partie-2}&quot;">​</a></h2><p>Cherchez les outils qui pourraient répondre à votre question. Pour chaque source consultée, notez dans la fiche :</p><table tabindex="0"><thead><tr><th style="text-align:left;">Colonne</th><th style="text-align:left;">Ce qu&#39;on y écrit</th></tr></thead><tbody><tr><td style="text-align:left;"><strong>Source</strong></td><td style="text-align:left;">Titre, site, date</td></tr><tr><td style="text-align:left;"><strong>Classement</strong></td><td style="text-align:left;">Fiable, à vérifier ou publicitaire</td></tr><tr><td style="text-align:left;"><strong>Indice</strong></td><td style="text-align:left;">Ce qui vous a fait trancher</td></tr><tr><td style="text-align:left;"><strong>Outils mentionnés</strong></td><td style="text-align:left;">Tous les outils que la source vous a fait découvrir, même ceux que vous ne retiendrez pas</td></tr></tbody></table><p>Vous ratissez large d&#39;abord, puis vous triez : à la fin, <strong>mettez en gras les 3 outils</strong> que vous retenez pour les essais, et expliquez sous le tableau, en une phrase par outil, quels besoins essentiels de la partie 1 il semble couvrir.</p><ul class="checklist"><li><label><input type="checkbox"><span class="check-text">Au moins <strong>5 sources</strong>, dont au moins <strong>une fiable</strong> et au moins <strong>un témoignage d&#39;utilisateurs</strong></span></label></li><li><label><input type="checkbox"><span class="check-text">Une <strong>liste courte de 3 outils</strong> à essayer, et une phrase pour dire pourquoi ceux-là</span></label></li><li><label><input type="checkbox"><span class="check-text">Au moins un outil qui fonctionne <strong>autrement</strong> des deux autres (un autre modèle de prix, une solution intégrée plutôt qu&#39;un service séparé…)</span></label></li></ul><div class="bg-slate-50 border border-slate-200 text-slate-800 rounded-lg p-4 mb-5"><strong>Pensez à ce qui existe déjà</strong><br> Le client utilise Wix, Square, Viator et Google Workspace. Un outil qui s&#39;intègre à ce qui existe n&#39;est pas forcément le meilleur, mais il faut l&#39;avoir regardé. Et l&#39;outil de votre question doit peut-être parler à celui d&#39;une autre équipe : la décharge (Q2) et la réservation (Q1) sont-elles dans le même outil ? </div><hr><h2 id="partie-3" tabindex="-1">Partie 3 — Lire les grilles de prix (10 min) <a class="header-anchor" href="#partie-3" aria-label="Permalink to &quot;Partie 3 — Lire les grilles de prix (10 min) {#partie-3}&quot;">​</a></h2><p>Pour chacun de vos trois outils, ouvrez la <strong>page de prix officielle</strong> et remplissez le tableau de la fiche.</p><table tabindex="0"><thead><tr><th style="text-align:left;">Ligne</th><th style="text-align:left;">Ce qu&#39;on y écrit</th></tr></thead><tbody><tr><td style="text-align:left;"><strong>Modèle de prix</strong></td><td style="text-align:left;">Au mois, à l&#39;utilisateur, à la transaction, gratuit avec limites, ou un mélange</td></tr><tr><td style="text-align:left;"><strong>Forfait qui répondrait aux besoins essentiels</strong></td><td style="text-align:left;">Son nom et son prix, tel qu&#39;affiché</td></tr><tr><td style="text-align:left;"><strong>Devise et facturation</strong></td><td style="text-align:left;">$ CA ou $ US ? Au mois ou à l&#39;année ?</td></tr><tr><td style="text-align:left;"><strong>Suppléments nécessaires</strong></td><td style="text-align:left;">Les modules payants dont Aventure Saint-Maurice aurait besoin</td></tr><tr><td style="text-align:left;"><strong>Estimation pour un an, en $ CA</strong></td><td style="text-align:left;">Votre calcul, avec les hypothèses de l&#39;activité 2</td></tr><tr><td style="text-align:left;"><strong>Essai gratuit</strong></td><td style="text-align:left;">Durée, carte de crédit exigée ?, fonctions bloquées pendant l&#39;essai</td></tr></tbody></table><div class="bg-red-50 border border-red-300 text-red-900 rounded-lg p-4 mb-5"><strong>Pas de prix affiché ?</strong><br> « Contactez-nous pour une soumission » est un constat en soi : notez-le. Ne communiquez pas avec le vendeur au nom d&#39;Aventure Saint-Maurice. Si vous trouvez un prix ailleurs (un témoignage, un comparatif), indiquez la source et son classement. </div><hr><h2 id="partie-4" tabindex="-1">Partie 4 — Le plan d&#39;essai (15 min) <a class="header-anchor" href="#partie-4" aria-label="Permalink to &quot;Partie 4 — Le plan d&#39;essai (15 min) {#partie-4}&quot;">​</a></h2><p>C&#39;est le cœur du lab. Écrivez <strong>6 à 8 essais</strong> que vous ferez sur <strong>chacun</strong> des trois outils, à la séance 4.</p><p>Chaque essai part d&#39;un <strong>scénario tiré du mandat</strong>, et précise ce que vous allez mesurer.</p><table tabindex="0"><thead><tr><th style="text-align:left;">Colonne</th><th style="text-align:left;">Ce qu&#39;on y écrit</th><th style="text-align:left;">Exemple (Q1)</th><th style="text-align:left;">Exemple (Q3)</th></tr></thead><tbody><tr><td style="text-align:left;"><strong>#</strong></td><td style="text-align:left;">Le numéro de l&#39;essai</td><td style="text-align:left;">E1</td><td style="text-align:left;">E4</td></tr><tr><td style="text-align:left;"><strong>Besoin vérifié</strong></td><td style="text-align:left;">Le besoin de la partie 1</td><td style="text-align:left;">Les places restantes sont à jour</td><td style="text-align:left;">Mélanie modifie elle-même les prix et les horaires</td></tr><tr><td style="text-align:left;"><strong>Scénario</strong></td><td style="text-align:left;">Ce que vous allez faire, avec des données précises</td><td style="text-align:left;">Créer un départ de via ferrata, samedi 10 h, 8 places. Réserver 5 places sur téléphone. Vérifier ce qu&#39;un deuxième client voit.</td><td style="text-align:left;">Dans l&#39;écran de gestion, faire passer le prix de la location de kayak à la journée de 45 $ à 49 $, et ajouter un départ de rabaska le dimanche à 13 h. Vérifier le résultat sur le site public, sur téléphone.</td></tr><tr><td style="text-align:left;"><strong>Côté</strong></td><td style="text-align:left;">Client, Mélanie (gestion) ou guide</td><td style="text-align:left;">Client puis Mélanie</td><td style="text-align:left;">Mélanie, jouée par le membre qui connaît le moins l&#39;outil, sans tutoriel</td></tr><tr><td style="text-align:left;"><strong>Ce qu&#39;on mesure</strong></td><td style="text-align:left;">Temps, nombre de clics, réussite ou échec, poids…</td><td style="text-align:left;">Le temps de réservation; il reste bien 3 places</td><td style="text-align:left;">Le temps; le nombre de fois où elle bloque; les deux changements sont visibles en ligne</td></tr><tr><td style="text-align:left;"><strong>Réussi si…</strong></td><td style="text-align:left;">Le critère, décidé <strong>avant</strong> l&#39;essai</td><td style="text-align:left;">Moins de 3 minutes sans aide, et 3 places affichées</td><td style="text-align:left;">Moins de 5 minutes, sans ouvrir l&#39;aide, et les deux changements visibles sur téléphone</td></tr></tbody></table><ul class="checklist"><li><label><input type="checkbox"><span class="check-text">Au moins <strong>un essai du côté du client</strong>, sur téléphone</span></label></li><li><label><input type="checkbox"><span class="check-text">Au moins <strong>un essai du côté de Mélanie</strong> : une tâche qu&#39;elle fera chaque semaine</span></label></li><li><label><input type="checkbox"><span class="check-text">Au moins <strong>un essai non fonctionnel</strong> : vitesse, accessibilité au clavier, réseau lent, langue…</span></label></li><li><label><input type="checkbox"><span class="check-text">Un essai de <strong>sortie</strong> : peut-on exporter les données, et dans quel format ?</span></label></li><li><label><input type="checkbox"><span class="check-text">Chaque essai a un critère « Réussi si… » <strong>mesurable</strong></span></label></li></ul><div class="bg-slate-50 border border-slate-200 text-slate-800 rounded-lg p-4 mb-5"><strong>Des outils pour mesurer</strong><br><ul class="list-disc pl-5"><li><strong>Le temps :</strong> un chronomètre de téléphone. Une personne manipule, l&#39;autre chronomètre et note.</li><li><strong>Un réseau lent :</strong> dans Chrome, outils de développement (F12) → onglet <em>Réseau</em> → <em>3G lente</em>.</li><li><strong>Le poids et la vitesse :</strong> PageSpeed Insights, comme au Lab 01.</li><li><strong>Le clavier :</strong> débranchez la souris et utilisez Tab, Maj+Tab et Entrée.</li></ul></div><hr><h2 id="partie-5" tabindex="-1">Partie 5 — L&#39;organisation (en fin de séance) <a class="header-anchor" href="#partie-5" aria-label="Permalink to &quot;Partie 5 — L&#39;organisation (en fin de séance) {#partie-5}&quot;">​</a></h2><p>Complétez le bas de la fiche :</p><ul><li><strong>Qui fait quoi à la séance 4 :</strong> qui manipule, qui chronomètre, qui prend les captures et les notes.</li><li><strong>Les comptes d&#39;essai :</strong> pour chaque outil, la date d&#39;ouverture prévue, l&#39;adresse courriel utilisée et la date d&#39;expiration.</li><li><strong>Les données inventées</strong> à préparer : noms de clients fictifs, horaire de départs, tarifs, une photo ou une vidéo de test (Q4), un texte à traduire (Q5)…</li></ul><hr><h2 id="remise" tabindex="-1">Remise <a class="header-anchor" href="#remise" aria-label="Permalink to &quot;Remise&quot;">​</a></h2><ul class="checklist"><li><label><input type="checkbox"><span class="check-text">6 à 8 besoins, classés essentiels ou souhaitables, avec leur source dans le mandat</span></label></li><li><label><input type="checkbox"><span class="check-text">Au moins 5 sources classées et justifiées, et une liste courte de 3 outils</span></label></li><li><label><input type="checkbox"><span class="check-text">Le tableau des prix rempli pour les 3 outils</span></label></li><li><label><input type="checkbox"><span class="check-text">6 à 8 essais, chacun avec un scénario précis et un critère de réussite mesurable</span></label></li><li><label><input type="checkbox"><span class="check-text">L&#39;organisation de la séance 4 et les dates des comptes d&#39;essai</span></label></li><li><label><input type="checkbox"><span class="check-text">Le fichier est nommé <code>lab03-equipeN-QX.docx</code> et déposé dans l&#39;équipe Teams du cours</span></label></li></ul><hr><h2 id="et-ensuite" tabindex="-1">Et ensuite ? <a class="header-anchor" href="#et-ensuite" aria-label="Permalink to &quot;Et ensuite ?&quot;">​</a></h2><p>À la <strong>séance 4 (21 octobre)</strong>, vous ferez vos essais, avec captures et chronomètre. Le retour en grand groupe portera sur les cinq questions : pour chacune, qu&#39;est-ce qui ressort, et pourquoi.</p><p>Dans l&#39;<strong>évaluation 1</strong>, la partie « Les possibilités techniques » s&#39;appuie directement sur ce travail : votre question en profondeur, grâce à vos essais, et les quatre autres en survol, grâce à votre propre recherche documentaire. La méthode de ce lab (sources classées, grilles de prix) vous servira pour chacune.</p>',47)])])}const h=t(i,[["render",n]]);export{g as __pageData,h as default};
